"""Regenerate Chess assets with the local constructors and Frame resources.

Run from the repository root: python -m dev_tools.chess_assets
"""
import json
from pathlib import Path

from dev_tools.assets_extract import ClickExtractor, ImageExtractor, OcrExtractor


ROOT = Path('tasks/Chess')


def generate():
    source = ('from module.atom.image import RuleImage\n'
              'from module.atom.frame import RuleFrame, Image, Ocr, Click\n'
              'from module.atom.click import RuleClick\n'
              'from module.atom.ocr import RuleOcr\n\n'
              '# Generated by python -m dev_tools.chess_assets; do not edit.\n'
              'class ChessAssets:\n')
    for filename, extractor in [('click.json', ClickExtractor),
                                ('image.json', ImageExtractor), ('ocr.json', OcrExtractor)]:
        path = ROOT / 'c' / filename
        source += extractor(str(path), json.loads(path.read_text(encoding='utf-8'))).result
    for rule in json.loads((ROOT / 'resource/c_frame.json').read_text(encoding='utf-8')):
        roi = lambda value: tuple(int(part) for part in value.split(','))
        badges = rule.get('badges') or [{'imageName': rule['imageName']}]
        args = dict(name=rule['itemName'], roi_badge=roi(rule['roiBadge']),
                    roi_range=[roi(value) for value in rule['roiRange']],
                    roi_back=roi(rule['roiBack']), method=rule['method'],
                    threshold=rule['threshold'],
                    badgefile=[str(next(path for path in
                                   (ROOT / 'resource' / item['imageName'], ROOT / 'c' / item['imageName'])
                                   if path.is_file())).replace('\\', '/')
                               for item in badges],
                    badge_grayscale=rule.get('badgeGrayscale', False))
        rendered = ', '.join(f'{key}={value!r}' for key, value in args.items())
        operations = []
        for operation in rule['rangeOperations']:
            operation = dict(operation)
            kind = operation.pop('type').title()
            if not operation.get('imageName'):
                operation.pop('imageName', None)
            kwargs = ', '.join(f'{key}={value!r}' for key, value in operation.items())
            operations.append(f'{kind}({kwargs})')
        rendered += ', range=[' + ', '.join(operations) + ']'
        name = rule['itemName'].upper()
        source += f'\n\tF_{name} = RuleFrame({rendered})\n\tI_{name} = F_{name}\n'
    return '\n'.join(line.rstrip() for line in source.splitlines()).rstrip() + '\n'


if __name__ == '__main__':
    (ROOT / 'assets.py').write_text(generate(), encoding='utf-8', newline='\n')
